#!/usr/bin/env python3
"""Normalized machine-code identity of Q06 serial hot paths.

usage: python3 hotpath_identity.py ROOT_FN LABEL=BINARY [LABEL=BINARY ...]
  e.g. python3 hotpath_identity.py p5_q06::query::blocks_bytes::execute \
           B=../baseline-original C=../candidate-original D=../dead-summary-worker

Walks direct and GOT-resolved calls from ROOT_FN (panic/fmt/alloc/mem* leaves skipped),
extracts each function with `objdump -d --no-show-raw-insn --start-address --stop-address`
(range from `nm -S`), and hashes the instruction stream after: dropping the address column;
intra-function branch targets -> <self+offset>; external call targets -> hash-free demangled
callee (rustfilt); GOT operands -> GOT[resolved callee]; other rip-relative operands -> RODATA.
"""
import hashlib, re, subprocess, sys

SKIP = ['panic', 'fmt::', 'Unwind', 'alloc::alloc::', 'handle_alloc', 'unwrap_failed', 'assert_failed',
        'drop_glue', '__rust', 'raw_vec', 'memset', 'memcpy', 'memmove', 'from_str', 'expect_failed',
        'slice_index_fail', 'index::slice_', 'capacity_overflow']

def load(path):
    syms, names = {}, []
    for line in subprocess.run(['nm', '-S', path], capture_output=True, text=True).stdout.splitlines():
        p = line.split()
        if len(p) == 4 and p[2] in 'tTwW':
            syms.setdefault(int(p[0], 16), (int(p[1], 16), []))[1].append(p[3])
            names.append(p[3])
    demangled = subprocess.run(['rustfilt'], input='\n'.join(names), capture_output=True, text=True).stdout.split('\n')
    dem = {n: re.sub(r'\.llvm\.\d+', '', d) for n, d in zip(names, demangled)}
    got = {}
    for line in subprocess.run(['readelf', '-rW', path], capture_output=True, text=True).stdout.splitlines():
        p = line.split()
        if len(p) >= 4 and p[2] == 'R_X86_64_RELATIVE':
            got[int(p[0], 16)] = int(p[3], 16)
        elif len(p) >= 5 and p[2] in ('R_X86_64_GLOB_DAT', 'R_X86_64_JUMP_SLOT'):
            got[int(p[0], 16)] = p[4].split('@')[0]
    return syms, dem, got

def name(syms, dem, x, fallback=None):
    if isinstance(x, str):
        return x
    return min(dem[n] for n in syms[x][1]) if x in syms else fallback

def normalize(path, a, size, syms, dem, got):
    text = subprocess.run(['objdump', '-d', '--no-show-raw-insn', f'--start-address={a:#x}',
                           f'--stop-address={a + size:#x}', path], capture_output=True, text=True).stdout
    out, callees = [], set()
    for line in text.splitlines():
        m = re.match(r'^\s*([0-9a-f]+):\t(.*)$', line)
        if not m:
            continue
        x = m.group(2).rstrip()
        b = re.match(r'^(call|j[a-z]+)\s+([0-9a-f]+) <([^>+]*)(\+0x[0-9a-f]+)?>$', x)
        if b:
            t = int(b.group(2), 16)
            if a <= t < a + size:
                x = f'{b.group(1)} <self+{t - a:#x}>'
            else:
                x = f'{b.group(1)} <{name(syms, dem, t, b.group(3))}>'
                callees.add(t)
            out.append(x)
            continue
        r = re.search(r'(-?0x[0-9a-f]+)\(%rip\)([^#]*)#\s+([0-9a-f]+)\s+<.*>$', x)
        if r:
            target = got.get(int(r.group(3), 16))
            callee = name(syms, dem, target) if target is not None else None
            if callee and not isinstance(target, str):
                callees.add(target)
            x = x[:r.start()] + (f'GOT[{callee}](%rip)' if callee else 'RODATA(%rip)') + r.group(2).rstrip()
        out.append(re.sub(r'\s+', ' ', x))
    return out, callees

def graph(path, root_name):
    syms, dem, got = load(path)
    stack = [a for a, (_, ns) in syms.items() if any(dem[n] == root_name for n in ns)]
    seen = {}
    while stack:
        a = stack.pop()
        if a in seen or a not in syms:
            continue
        fn = name(syms, dem, a)
        if any(k in fn for k in SKIP):
            continue
        body, callees = normalize(path, a, syms[a][0], syms, dem, got)
        seen[a] = (fn, body)
        stack.extend(callees)
    return {fn: (a, hashlib.sha256('\n'.join(body).encode()).hexdigest(), len(body)) for a, (fn, body) in seen.items()}

def main():
    root, pairs = sys.argv[1], [arg.split('=', 1) for arg in sys.argv[2:]]
    graphs = {label: graph(path, root) for label, path in pairs}
    labels = [label for label, _ in pairs]
    print(f'## {root}: ' + ' '.join(f'{l}={len(graphs[l])}' for l in labels))
    for fn in sorted(set().union(*graphs.values())):
        cells = []
        for l in labels:
            a, h, n = graphs[l].get(fn, (0, 'missing', 0))
            cells.append(f'{l}:{n}:{h[:16]}:{a:x}({a % 64:02x}/{a % 4096:03x})')
        same = len({graphs[l].get(fn, (0, 'missing'))[1] for l in labels}) == 1
        print(('SAME ' if same else 'DIFF ') + ' '.join(cells) + '  ' + (fn if len(fn) < 150 else fn[:75] + ' … ' + fn[-60:]))

if __name__ == '__main__':
    main()

